-- Seed OBAT MINUM (oral, bisa diresepkan). Idempoten via kode_produk unik (OBM-###).
-- pajak 11%, komisi dokter 5% margin, stok awal 0 (isi via PO), tipe RETAIL. Nama obat apa adanya + kandungan; golongan disimpan.
USE db_sehati;
ON DUPLICATE KEY UPDATE nama_produk=VALUES(nama_produk), satuan=VALUES(satuan), harga_jual=VALUES(harga_jual), pajak_persen=VALUES(pajak_persen), komisi_dokter_tipe=VALUES(komisi_dokter_tipe), komisi_dokter_value=VALUES(komisi_dokter_value), kandungan=VALUES(kandungan), golongan=VALUES(golongan);
SELECT golongan, COUNT(*) FROM master_produk WHERE kode_produk LIKE 'OBM-%' GROUP BY golongan ORDER BY MIN(id_produk);
SELECT COUNT(*) AS total_obat FROM master_produk WHERE kode_produk LIKE 'OBM-%';
